import { findConflicts } from './src/booking-conflicts.js';
import assert from 'node:assert/strict';
const B = (id, room, start, end) => ({ id, room, start, end });
const ok = '2026-03-01T09:00:00Z', end = '2026-03-01T10:00:00Z';

// R1
for (const bad of [null, {}, 'x', 42]) assert.throws(() => findConflicts(bad), TypeError);
for (const b of [
  { id: '', room: 'R', start: ok, end },
  { id: 1, room: 'R', start: ok, end },
  { id: 'a', room: '', start: ok, end },
  { id: 'a', room: 'R', start: '2026-02-30T10:00:00Z', end },
  { id: 'a', room: 'R', start: ok, end: '2026-03-01 10:00:00Z' },
  { id: 'a', room: 'R', start: '2026-03-01T24:00:00Z', end },
  { id: 'a', room: 'R', start: '2025-02-29T10:00:00Z', end },
  { id: 'a', room: 'R', start: ok, end: '2026-03-01T10:00:60Z' },
]) assert.throws(() => findConflicts([b]), TypeError);

// R2
assert.throws(() => findConflicts([B('a','R',ok,ok)]), RangeError);
assert.throws(() => findConflicts([B('a','R',end,ok)]), RangeError);
assert.throws(() => findConflicts([B('a','R',ok,end), B('a','R',end,'2026-03-01T11:00:00Z')]), TypeError);
// R3 order: bad end (RangeError) on booking i beats later booking's R1 problem
assert.throws(() => findConflicts([B('a','R',ok,ok), { room: 'R' }]), RangeError);
// R3 order: R1 on booking i beats its own duplicate id
assert.throws(() => findConflicts([B('a','R',ok,end), { id: 'a', room: '', start: ok, end }]), TypeError);
// dup id check is against earlier bookings only, checked after end check
assert.throws(() => findConflicts([B('a','R',ok,end), B('a','R','2026-03-01T09:00:00Z','2026-03-01T08:00:00Z')]), RangeError);

// R4: touching no conflict, identical conflict, contained conflict, case-sensitive rooms
assert.deepEqual(findConflicts([
  B('a','R1',ok,end),
  B('b','R1',end,'2026-03-01T11:00:00Z'),
]), []);
assert.deepEqual(findConflicts([
  B('a','R1',ok,end),
  B('b','R1',ok,end),
]), [['a','b']]);
assert.deepEqual(findConflicts([
  B('a','R1','2026-03-01T08:00:00Z','2026-03-01T12:00:00Z'),
  B('b','R1',ok,end),
  B('c','R1','2026-03-01T09:00:01Z','2026-03-01T09:30:00Z'),
]), [['a','b'],['a','c'],['b','c']]);
assert.deepEqual(findConflicts([
  B('a','A1',ok,end), B('b','a1',ok,end),
]), []);

// R5 sorting + R6 immutability
const input = [
  B('b','R1','2026-03-01T09:00:00Z','2026-03-01T10:00:00Z'),
  B('a','R1','2026-03-01T09:30:00Z','2026-03-01T11:00:00Z'),
  B('c','R2','2026-03-01T09:00:00Z','2026-03-01T10:00:00Z'),
];
const copy = JSON.parse(JSON.stringify(input));
const res = findConflicts(input);
assert.deepEqual(res, [['a','b']]);
assert.deepEqual(input, copy);
assert.deepEqual(findConflicts([]), []);
// valid: leap day, second boundary
assert.deepEqual(findConflicts([B('a','R','2024-02-29T23:59:59Z','2024-03-01T00:00:00Z')]), []);
console.log('all sanity checks passed');
"
